// Measured data for every font in lib/realfonts.ts, generated by
// scripts/fontstats.py from Google Fonts metadata and the font files
// themselves. Shown as "our measurement" on /fonts pages.
import stats from "./fontstats.json";
import type { RealFont } from "./realfonts";
import { GROUP_LABEL } from "./realfonts";

export type FontStats = {
  license: string;
  added: string;
  weights: string;
  italic: boolean;
  glyphs: number;
  chars: number;
  longS: boolean;
  german: boolean;
  latinExt: boolean;
  digits: boolean;
};

export const FONT_STATS = stats as Record<string, FontStats>;

/** Date the stats were last measured (bump when re-running fontstats.py). */
export const STATS_VERIFIED = "2026-11-11";

const yes = (b: boolean) => (b ? "Yes" : "No");

export const COMPARE_HEAD = ["Font", "Style", "Glyphs", "Weights", "Long s (ſ)", "ß and umlauts", "Extended Latin", "On Google Fonts since"];

export function compareRow(f: RealFont): string[] {
  const s = FONT_STATS[f.family];
  if (!s) return [f.family, GROUP_LABEL[f.group], "—", "—", "—", "—", "—", String(f.added)];
  return [f.family, GROUP_LABEL[f.group], String(s.glyphs), s.weights + (s.italic ? " + italic" : ""), yes(s.longS), yes(s.german), yes(s.latinExt), s.added.slice(0, 4)];
}

/** Facts table rows for a single-font page. */
export function factRows(f: RealFont): string[][] {
  const s = FONT_STATS[f.family];
  const rows: string[][] = [
    ["Designer", f.designers],
    ["Style", GROUP_LABEL[f.group]],
    ["Licence", "SIL Open Font License 1.1 (free for personal and commercial use)"],
  ];
  if (s) {
    rows.push(
      ["Added to Google Fonts", s.added],
      ["Weights", s.weights + (s.italic ? ", with italic" : ", no italic")],
      ["Glyphs in the font file", `${s.glyphs} (${s.chars} mapped characters)`],
      ["Long s (ſ)", yes(s.longS)],
      ["German ß and umlauts", yes(s.german)],
      ["Central European letters (ą č ł ő ř …)", yes(s.latinExt)],
      ["Digits 0–9", yes(s.digits)],
    );
  }
  return rows;
}
